const e="n4-test-1",t="N4",o="JLPT N4 Practice Test 1",n={vocabulary:{timeLimit:25,questions:[{id:"v1",type:"kanji-reading",question:"あした、東京へ【出張】します。",options:["しゅっしょう","しゅっちょう","しゅちょう","しゅっちょ"],correctAnswer:1,explanation:"出張 (しゅっちょう) means 'business trip'."},{id:"v2",type:"kanji-reading",question:"駅の前に大きい【建物】があります。",options:["たてもの","けんぶつ","たてもの","けんもの"],correctAnswer:0,explanation:"建物 (たてもの) means 'building'."},{id:"v3",type:"kanji-reading",question:"このカメラは【便利】です。",options:["べんり","ふべん","へんり","びんり"],correctAnswer:0,explanation:"便利 (べんり) means 'convenient'."},{id:"v4",type:"kanji-reading",question:"【試合】は10時から始まります。",options:["しあい","じあい","しごう","じごう"],correctAnswer:0,explanation:"試合 (しあい) means 'game' or 'match'."},{id:"v5",type:"kanji-reading",question:"ここから山が見えるか【確かめて】ください。",options:["たしかめて","あきらめて","しらべて","きめて"],correctAnswer:0,explanation:"確かめる (たしかめる) means 'to confirm'."},{id:"v6",type:"kanji-reading",question:"少し【気分】が悪いです。",options:["きぶん","きふん","けぶん","きもち"],correctAnswer:0,explanation:"気分 (きぶん) means 'feeling' or 'mood' (especially regarding health)."},{id:"v7",type:"kanji-reading",question:"【急いで】行きましょう。",options:["いそいで","さわいで","およいで","ぬいで"],correctAnswer:0,explanation:"急ぐ (いそぐ) means 'to hurry'."},{id:"v8",type:"orthography",question:"あした【じゅんび】をします。",options:["準備","準傭","準備","準美"],correctAnswer:0,explanation:"準備 (じゅんび) is the kanji for preparation."},{id:"v9",type:"orthography",question:"【うんてん】が上手です。",options:["運点","運動","運転","運店"],correctAnswer:2,explanation:"運転 (うんてん) is the kanji for driving."},{id:"v10",type:"orthography",question:"あの【けいけん】は大切でした。",options:["経験","経済","経検","経険"],correctAnswer:0,explanation:"経験 (けいけん) is the kanji for experience."},{id:"v11",type:"orthography",question:"【あんない】をお願いします。",options:["案内","案肉","行内","案無い"],correctAnswer:0,explanation:"案内 (あんない) is the kanji for guidance/information."},{id:"v12",type:"orthography",question:"【きそく】を守ってください。",options:["規則","規側","記則","規息"],correctAnswer:0,explanation:"規則 (きそく) is the kanji for rules/regulations."},{id:"v13",type:"orthography",question:"【やくそく】を忘れないでください。",options:["約束","約東","約足","約遠"],correctAnswer:0,explanation:"約束 (やくそく) is the kanji for promise."},{id:"v14",type:"context",question:"かぜをひいたので、学校に（　　）をしました。",options:["れんらく","やくそく","しょうかい","ちゅうい"],correctAnswer:0,explanation:"連絡 (れんらく) means to contact someone (to call in sick)."},{id:"v15",type:"context",question:"ガラスが（　　）しまいました。",options:["おれて","やぶれて","われて","たおれて"],correctAnswer:2,explanation:"割れる (われる) is used for glass or plates breaking."},{id:"v16",type:"context",question:"テストの前に（　　）をします。",options:["ふくしゅう","しゅくだい","じゅぎょう","しつもん"],correctAnswer:0,explanation:"復習 (ふくしゅう) means review, which you do before a test."},{id:"v17",type:"context",question:"（　　）、このカメラの使い方を教えてくれませんか。",options:["すみませんが","ありがとう","こんにちは","ごめんなさい"],correctAnswer:0,explanation:"すみませんが (Excuse me, but...) is used when asking for a favor."},{id:"v18",type:"context",question:"駅まで歩いて5分（　　）です。",options:["だけ","ごろ","ぐらい","など"],correctAnswer:2,explanation:"ぐらい means 'about' (approximate duration/amount)."},{id:"v19",type:"context",question:"道が（　　）いて、遅れました。",options:["すいて","こんで","あいて","つまって"],correctAnswer:1,explanation:"混む (こむ) means to be crowded (道がこむ = traffic jam)."},{id:"v20",type:"context",question:"このスープは少し（　　）ですね。もう少し塩を入れましょう。",options:["あまい","からい","うすい","こい"],correctAnswer:2,explanation:"薄い (うすい) means weak/thin (in flavor), so you'd add salt."},{id:"v21",type:"context",question:"あの店は（　　）から、よく行きます。",options:["サービス","デザイン","スタイル","ルール"],correctAnswer:0,explanation:"サービスがいい (good service) is a reason to frequent a shop."},{id:"v22",type:"context",question:"ボタンを（　　）と、切符が出ます。",options:["おす","ひく","まわす","さわる"],correctAnswer:0,explanation:"押す (おす) means to press (a button)."},{id:"v23",type:"context",question:"田中さんの（　　）はピアノを弾くことです。",options:["しゅみ","しごと","ゆめ","きぼう"],correctAnswer:0,explanation:"趣味 (しゅみ) is a hobby, like playing the piano."},{id:"v24",type:"paraphrase",question:"木村さんは【真面目な】人です。",options:["木村さんはよく勉強や仕事をします。","木村さんはよく遊びます。","木村さんは面白いです。","木村さんはよく休みます。"],correctAnswer:0,explanation:"真面目 (まじめ) means serious/earnest, so they work and study hard."},{id:"v25",type:"paraphrase",question:"会議は【中止になりました】。",options:["会議は始まりました。","会議は終わりました。","会議はなくなりました。","会議は明日になりました。"],correctAnswer:2,explanation:"中止になる (to be canceled) means it won't happen (なくなりました)."},{id:"v26",type:"paraphrase",question:"私は【たまに】映画を見ます。",options:["私はよく映画を見ます。","私はときどき映画を見ます。","私は全然映画を見ません。","私は毎日映画を見ます。"],correctAnswer:1,explanation:"たまに (occasionally) is similar to ときどき (sometimes)."},{id:"v27",type:"paraphrase",question:"この仕事は【大変です】。",options:["この仕事は面白いです。","この仕事は難しいです。","この仕事は簡単です。","この仕事はとても疲れます。"],correctAnswer:3,explanation:"大変 (tough/hard) implies it makes you very tired (とても疲れます)."},{id:"v28",type:"paraphrase",question:"友達に車を【貸しました】。",options:["友達は私の車を使いました。","私は友達の車を使いました。","友達は車を買いました。","私は車を買いました。"],correctAnswer:0,explanation:"貸す (to lend) means the friend used my car."},{id:"v29",type:"paraphrase",question:"【さっき】、田中さんに会いました。",options:["少し前に田中さんに会いました。","今、田中さんに会いました。","これから田中さんに会います。","きのう田中さんに会いました。"],correctAnswer:0,explanation:"さっき means 'a little while ago' (少し前に)."},{id:"v30",type:"paraphrase",question:"お湯が【沸きました】。",options:["お湯が冷たくなりました。","お湯が熱くなりました。","お湯が少なくなりました。","お湯がなくなりました。"],correctAnswer:1,explanation:"沸く (to boil) means the water became hot (熱くなりました)."}]},grammar:{timeLimit:25,questions:[{id:"g1",type:"grammar-fill",question:"あしたは雨が降る（　　）があります。",options:["はず","かも知れません","でしょう","こと"],correctAnswer:1,explanation:"〜かも知れません (might) is used for probability. (でしょう is also possible, but usually just '降るでしょう' not '降るでしょう。' if used directly, 'かも知れません' is safer if 'でしょう' is an option but wait. Let's make it unambiguous: 'かもしれません')."},{id:"g2",type:"grammar-fill",question:"すみません、このペンを（　　）いいですか。",options:["使うと","使えば","使っても","使って"],correctAnswer:2,explanation:"〜てもいいですか is used to ask for permission (May I use?)."},{id:"g3",type:"grammar-fill",question:"風邪をひいたので、あしたは学校を（　　）ください。",options:["休まないで","休んで","休ませて","休まれて"],correctAnswer:2,explanation:"休ませてください (Please let me rest) uses the causative te-form + ください."},{id:"g4",type:"grammar-fill",question:"このケーキは私が（　　）ケーキです。",options:["作る","作って","作った","作ろう"],correctAnswer:2,explanation:"Past tense plain form (作った) modifies the noun (the cake I made)."},{id:"g5",type:"grammar-fill",question:"山田さんは英語が（　　）そうです。",options:["わかる","わかり","わかるの","わかって"],correctAnswer:0,explanation:"〜そうです (I heard that...) follows the plain form of a verb (わかる)."},{id:"g6",type:"grammar-fill",question:"本を（　　）まま、寝てしまいました。",options:["読む","読んだ","読んで","読もう"],correctAnswer:1,explanation:"〜たまま (leaving things as they are) requires the past plain form (読んだ)."},{id:"g7",type:"grammar-fill",question:"テレビを（　　）ながら、ご飯を食べます。",options:["見る","見て","見","見た"],correctAnswer:2,explanation:"〜ながら (while doing) requires the verb stem (見)."},{id:"g8",type:"grammar-fill",question:"道がわからない場合は、交番で（　　）ください。",options:["聞く","聞いて","聞いた","聞き"],correctAnswer:1,explanation:"〜てください requires the te-form (聞いて)."},{id:"g9",type:"grammar-fill",question:"私は毎日、野菜を食べる（　　）しています。",options:["ように","ために","ことに","からに"],correctAnswer:0,explanation:"〜ようにしています means 'I make it a rule to / I try to'."},{id:"g10",type:"grammar-fill",question:"田中さんに荷物を（　　）。",options:["持たせました","持ちました","持たれました","持ってくれました"],correctAnswer:0,explanation:"持たせる (causative) means 'made/had Tanaka carry the luggage'."},{id:"g11",type:"grammar-fill",question:`次の文の ★ に入る最もよいものを一つ選びなさい。
ここ ___ ___ ★ ___ いけません。`,options:["車","を","は","とめては"],correctAnswer:3,explanation:"The correct order is: ここには車をとめてはいけません。 The star is 'とめては'."},{id:"g12",type:"grammar-fill",question:"きのう ___ ___ ★ ___ を ___ しまいました。",options:["買った","なくして","ばかり","の傘"],correctAnswer:2,explanation:"The correct order is: きのう買ったばかりの傘をなくしてしまいました。 The star is 'ばかり'."},{id:"g13",type:"grammar-fill",question:"彼 ___ ___ ★ ___ を ___ があります。",options:["たこと","は","食べ","納豆"],correctAnswer:0,explanation:"The correct order is: 彼は納豆を食べたことがあります。 The star is 'たこと'."},{id:"g14",type:"grammar-fill",question:"早く ___ ___ ★ ___ なりますよ。",options:["病気","に","休まない","と"],correctAnswer:1,explanation:"The correct order is: 早く休まないと病気になりますよ。 The star is 'に'."},{id:"g15",type:"grammar-fill",question:"先生 ___ ___ ★ ___ が ___ ました。",options:["に","名前","を","呼ばれ"],correctAnswer:2,explanation:"The correct order is: 先生に名前を呼ばれました。 The star is 'を'."},{id:"g16",type:"grammar-fill",question:`文章を読んで、（１）に入る言葉を選びなさい。
私は日本へ（１）から、１年になります。`,options:["来る","来て","来た","来ない"],correctAnswer:1,explanation:"〜てから (since doing) requires the te-form (来て)."},{id:"g17",type:"grammar-fill",question:`（２）に入る言葉を選びなさい。
最初、日本の生活は（２）が、今は慣れました。`,options:["大変です","大変でした","大変になります","大変になりました"],correctAnswer:1,explanation:"Describing a past state requires past tense (大変でした)."},{id:"g18",type:"grammar-fill",question:`（３）に入る言葉を選びなさい。
日本語も少し（３）ようになりました。`,options:["話す","話せる","話し","話して"],correctAnswer:1,explanation:"〜ようになる (to reach the point where) often takes potential form (話せる)."},{id:"g19",type:"grammar-fill",question:`（４）に入る言葉を選びなさい。
でも、まだ漢字が（４）読めません。`,options:["あまり","とても","ぜんぜん","たくさん"],correctAnswer:0,explanation:"あまり〜ない means 'not very well/much'."},{id:"g20",type:"grammar-fill",question:`（５）に入る言葉を選びなさい。
だから、毎日漢字を（５）ようにしています。`,options:["覚える","覚えた","覚えて","覚えよう"],correctAnswer:0,explanation:"〜ようにしています requires dictionary form (覚える)."},{id:"g21",type:"grammar-fill",question:`（６）に入る言葉を選びなさい。
来月、JLPTのN4の試験を（６）つもりです。`,options:["受ける","受けた","受けて","受けよう"],correctAnswer:0,explanation:"〜つもりです requires dictionary form (受ける)."},{id:"g22",type:"grammar-fill",question:`（７）に入る言葉を選びなさい。
試験に（７）、両親も喜んでくれるでしょう。`,options:["合格すると","合格すれば","合格したら","合格して"],correctAnswer:2,explanation:"〜たら (if/when) is natural here: 合格したら (If I pass)."},{id:"g23",type:"grammar-fill",question:`（８）に入る言葉を選びなさい。
合格する（８）、頑張ります。`,options:["ように","ために","から","ので"],correctAnswer:1,explanation:"合格するために (In order to pass). 'ように' is also possible with potential/intransitive, but 'ために' is used with absolute intention."}]},reading:{timeLimit:55,passages:[{id:"p1",text:"私は先週、友達と富士山に登りました。夜の10時に登り始めて、次の日の朝5時に頂上に着きました。とても寒くて大変でしたが、頂上から見た太陽はとても美しくて、感動しました。またいつか登りたいです。",questions:[{id:"r1",type:"reading-comprehension",question:"この人は富士山に登るのに何時間かかりましたか。",options:["5時間","7時間","10時間","12時間"],correctAnswer:1,explanation:"From 10 PM to 5 AM is 7 hours (7時間)."},{id:"r2",type:"reading-comprehension",question:"富士山に登って、どう思いましたか。",options:["寒くて、もう登りたくない","大変だったが、また登りたい","夜は登らないほうがいい","太陽は見えなかった"],correctAnswer:1,explanation:"The text says '大変でしたが... またいつか登りたいです' (It was tough, but I want to climb it again someday)."}]},{id:"p2",text:"最近、若い人の間で「スマートウォッチ」が人気です。時間を見るだけでなく、電話をかけたり、メールを読んだりすることができます。また、歩いた歩数や心拍数を測ることもできるので、健康のために使う人も多いです。",questions:[{id:"r3",type:"reading-comprehension",question:"スマートウォッチでできないことは何ですか。",options:["電話をかけること","メールを読むこと","心拍数を測ること","料理を作ること"],correctAnswer:3,explanation:"The text mentions making calls, reading emails, and measuring heart rate. It does not say it can cook."},{id:"r4",type:"reading-comprehension",question:"どうして健康のために使う人が多いのですか。",options:["安くて便利だから","時間がわかるから","歩数や心拍数が測れるから","若者に人気があるから"],correctAnswer:2,explanation:"The text says '歩いた歩数や心拍数を測ることもできるので、健康のために使う人も多いです' (Because you can measure steps and heart rate, many use it for health)."}]},{id:"p3",text:`【市民センターの料理教室について】
・日時：毎週土曜日 午前10時〜午後1時
・場所：市民センター3階 調理室
・参加費：1回 1,500円（材料費を含みます）
・持ち物：エプロン、タオル
※参加したい人は、木曜日までに電話で予約してください。`,questions:[{id:"r5",type:"reading-comprehension",question:"料理教室はどのくらい時間がかかりますか。",options:["1時間","2時間","3時間","4時間"],correctAnswer:2,explanation:"From 10 AM to 1 PM is 3 hours (3時間)."},{id:"r6",type:"reading-comprehension",question:"参加費について正しいのはどれですか。",options:["1500円のほかに材料費を払う","1500円だけで材料費も入っている","材料は自分で買っていく","お金はかからない"],correctAnswer:1,explanation:"The text says '（材料費を含みます）' (Includes material costs)."},{id:"r7",type:"reading-comprehension",question:"金曜日に予約の電話をしました。参加できますか。",options:["できる","できない","エプロンがあればできる","先生に聞かなければならない"],correctAnswer:1,explanation:"The text says '木曜日までに' (by Thursday). Friday is too late."}]}]}},i={id:e,level:t,title:o,sections:n};export{i as default,e as id,t as level,n as sections,o as title};
